export type PlaygroundEvent = { id: string; launch: number; burst: number; shape: string; colors: string[]; life: number; seed: number; x: number; launchVisible: boolean; arms?: number };
export type PlaygroundProfile = { productId: string; name: string; brand: string; category: string; kind: string; sampleLabel: string; duration: number; observedShots: number | null; effects: string[]; summary: string; source: { url: string; segmentStart: number; segmentEnd: number }; events: PlaygroundEvent[] };
export function buildPlaygroundDocument(options: { profiles: PlaygroundProfile[]; skyline: string; compact?: boolean; reducedMotion?: boolean; scene?: string; bases?: Record<string, { src: string; crop: number[]; aspect: number; nozzle: number[]; nozzles?: number[][]; scale?: number }> }): string;
